// ─── File: HashingDemo.java ───
package com.bank.hashing;

import java.util.*;
import java.util.logging.*;

public class HashingDemo {
    private static final Logger log = Logger.getLogger("Hash");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<String> keys = new ArrayList<>();
        for (int i = 0; i < 1000; i++) keys.add("balance:ACC" + i);

        // Consistent hashing with 3 nodes
        ConsistentHashRing ring = new ConsistentHashRing(100);
        ring.addNode("cache-A"); ring.addNode("cache-B"); ring.addNode("cache-C");
        Map<String,String> before = new HashMap<>();
        for (String k : keys) before.put(k, ring.nodeFor(k));

        // Add a 4th node → count how many keys move
        ring.addNode("cache-D");
        int movedConsistent = 0;
        for (String k : keys) if (!before.get(k).equals(ring.nodeFor(k))) movedConsistent++;
        int finalMoved = movedConsistent;
        log.info(() -> "Consistent hashing: " + finalMoved + "/1000 keys moved on add (~K/N)");

        // Contrast with naive modulo: adding a node remaps almost everything
        NaiveModuloHashing naive3 = new NaiveModuloHashing(3);
        NaiveModuloHashing naive4 = new NaiveModuloHashing(4);
        int movedNaive = 0;
        for (String k : keys) if (naive3.nodeFor(k) != naive4.nodeFor(k)) movedNaive++;
        int fm = movedNaive;
        log.info(() -> "Naive modulo: " + fm + "/1000 keys moved on add (nearly all)");

        // Remove a node → only its keys move
        Map<String,String> beforeRemove = new HashMap<>();
        for (String k : keys) beforeRemove.put(k, ring.nodeFor(k));
        ring.removeNode("cache-B");
        int movedOnRemove = 0;
        for (String k : keys) if (!beforeRemove.get(k).equals(ring.nodeFor(k))) movedOnRemove++;
        int mr = movedOnRemove;
        log.info(() -> "On removing cache-B: " + mr + "/1000 keys moved (only its share)");
    }
}

